using System.Text.Json;
using System.Text.Json.Nodes;
using System.Windows;
using System.Windows.Controls;
namespace ArchiveReader;
public partial class AgentWindow:Window
{
 readonly string page;readonly Func<string,JsonObject?,CancellationToken,Task<JsonNode>> worker;bool busy;CancellationTokenSource? work;
 static string T(string s)=>Localizer.Text(s);
 public AgentWindow(string page,Func<string,JsonObject?,CancellationToken,Task<JsonNode>> worker,string model){this.page=page;this.worker=worker;InitializeComponent();ModelA.Text=model;for(var directory=new System.IO.DirectoryInfo(AppDomain.CurrentDomain.BaseDirectory);directory!=null;directory=directory.Parent){if(string.IsNullOrWhiteSpace(ModelA.Text)){var a=System.IO.Path.Combine(directory.FullName,"models","german-handwriting","model.mlmodel");if(System.IO.File.Exists(a))ModelA.Text=a;}var candidate=System.IO.Path.Combine(directory.FullName,"models","polish-metrical-experimental");if(System.IO.Directory.Exists(candidate)){ModelB.Text=candidate;break;}}Loaded+=async(_,_)=>await Run(async()=>{Localizer.Apply(this,Localizer.Language);Regions.ItemsSource=(await Call("annotations",new(){["id"]=page})).AsArray().Where(n=>n?["kind"]?.ToString()=="line").Select(n=>new GenealogyRow(n!.AsObject(),n["text"]?.ToString() is string s && s.Length>0?s:n["id"]!.ToString())).ToList();Regions.SelectedIndex=0;await Refresh();if(Environment.GetCommandLineArgs().Contains("--smoke-agents")){if(Jobs.SelectedItem is GenealogyRow selected)await LoadEvidence(selected);SmokeCapture.Save(this,"agents-ui","workflow.png");Close();}});Closing+=(_,_)=>work?.Cancel();}
 void StopWork(object sender,RoutedEventArgs e)=>work?.Cancel();
 void ChooseModel(object sender,RoutedEventArgs e){if((sender as Button)?.Tag.ToString()=="A"){var d=new Microsoft.Win32.OpenFileDialog{Filter="Kraken|*.mlmodel;*.safetensors"};if(d.ShowDialog()==true)ModelA.Text=d.FileName;}else{var d=new Microsoft.Win32.OpenFolderDialog();if(d.ShowDialog()==true)ModelB.Text=d.FolderName;}}
 Task<JsonNode> Call(string command,JsonObject args)=>worker(command,args,work?.Token??default);
 async Task Run(Func<Task> action){if(busy)return;busy=true;work=new();try{await action();}catch(OperationCanceledException){Status.Text=T("Обробку зупинено. Збережені результати залишилися в бібліотеці.");}catch(Exception ex){Status.Text=T(ex.Message);}finally{busy=false;work.Dispose();work=null;}}
 string? Selected=> (Jobs.SelectedItem as GenealogyRow)?.Data["id"]?.ToString();
 async Task Refresh(string? selected=null){Jobs.ItemsSource=(await Call("agent_jobs",new(){["page"]=page})).AsArray().Select(n=>new GenealogyRow(n!.AsObject(),n["id"]!.ToString()[..8]+" · "+n["state"])).ToList();Jobs.SelectedItem=Jobs.Items.Cast<GenealogyRow>().FirstOrDefault(r=>r.Data["id"]?.ToString()==selected)??Jobs.Items.Cast<GenealogyRow>().FirstOrDefault();}
 async void Create(object sender,RoutedEventArgs e)=>await Run(async()=>{if(Regions.SelectedItem is not GenealogyRow region)return;var result=await Call("agent_create",new(){["page"]=page,["annotation"]=region.Data["id"]!.ToString(),["models"]=new JsonArray(new JsonObject{["name"]="A",["engine"]="kraken",["path"]=ModelA.Text},new JsonObject{["name"]="B",["engine"]="trocr",["path"]=ModelB.Text})});await Refresh(result["id"]!.ToString());});
 async void Step(object sender,RoutedEventArgs e)=>await Run(async()=>{if(Selected is string id){await Call("agent_step",new(){["job"]=id});await Refresh(id);}});
 async void CancelJob(object sender,RoutedEventArgs e)=>await Run(async()=>{if(Selected is string id){await Call("agent_cancel",new(){["job"]=id});await Refresh(id);}});
 async void Review(object sender,RoutedEventArgs e)=>await Run(async()=>{if(Selected is string id){await Call("agent_review",new(){["job"]=id,["text"]=Correction.Text,["checked"]=Checked.IsChecked==true});await Refresh(id);Status.Text=T("Приклад збережено окремо. Автоматичного донавчання немає.");}});
 async void TrainCandidate(object sender,RoutedEventArgs e)=>await Run(async()=>{Status.Text=T("Навчання окремої моделі та перевірка можуть тривати довго.");var result=await Call("candidate_train_check",new(){["model"]=ModelA.Text,["epochs"]=1});Report.Text=T("Результат перевірки моделі")+": "+result["status"]+"\n"+(result["message"]?.ToString()??result["error"]?.ToString()??"")+"\n"+result["candidate"]+"\n"+T("Базова модель залишається активною. Покращення потребує ручної оцінки.")+"\n"+T("Перевірені рядки")+": "+result["common_lines"]+"\nCER A: "+Percent(result["cer"]?["base"])+" · CER B: "+Percent(result["cer"]?["candidate"])+"\n"+T("Невдалі спроби")+": A "+result["failures"]?["base"]+" · B "+result["failures"]?["candidate"];Status.Text=T("Завершено");});
 static string Percent(JsonNode? value)=>value==null?"—":value.GetValue<double>().ToString("P1");
 string Readable(JsonObject job){var lines=new List<string>{T("Стан завдання")+": "+T(job["state"]?.ToString() switch{"layout"=>"Перевірка меж рядка","recognition"=>"Незалежне розпізнавання","comparison"=>"Порівняння прочитань","review"=>"Очікує перевірки людиною","complete"=>"Завершено","cancelled"=>"Скасовано",_=>"Помилка"})};if(job["error"]!=null)lines.Add(job["error"]!.ToString());if(job["stages"]?["recognition"]?["rows"] is JsonArray rows)foreach(var row in rows){if(row?["results"] is JsonObject results)foreach(var model in results){lines.Add("\n"+model.Key+": "+(model.Value?["text"]?.ToString()??model.Value?["error"]?.ToString()??""));}lines.Add("\n"+T(row?["ensemble"]?["status"]?.ToString()=="agreed_unverified"?"Моделі погодилися. Потрібна перевірка оригіналу.":"Прочитання потребують перевірки оригіналу."));}return string.Join("\n",lines);}
 async void SelectJob(object sender,SelectionChangedEventArgs e){if(Jobs.SelectedItem is GenealogyRow row){Report.Text=Readable(row.Data);Correction.Text=row.Data["feedback"]?["text"]?.ToString()??"";Checked.IsChecked=false;try{await LoadEvidence(row);}catch(OperationCanceledException){Status.Text=T("Обробку зупинено. Збережені результати залишилися в бібліотеці.");}catch(Exception ex){Status.Text=T(ex.Message);}}}
 async Task LoadEvidence(GenealogyRow row){var result=await Call("region_crop",new(){["id"]=page,["annotation"]=row.Data["annotation"]!.ToString()});if(!ReferenceEquals(Jobs.SelectedItem,row))return;var image=new System.Windows.Media.Imaging.BitmapImage();image.BeginInit();image.CacheOption=System.Windows.Media.Imaging.BitmapCacheOption.OnLoad;image.UriSource=new Uri(result["path"]!.ToString());image.EndInit();image.Freeze();Evidence.Source=image;}

}
